from pathlib import Path
import json

ROOT=Path.home()/".local/share/prediction-project-executor/campaigns/FULL-A2Z-LIVE-20261004-V4/models"
TASK="A2Z-V4-ASTRA-PREBUILD-DIRECT-20261007-R4P2"
out={}
for name in ("STATE.json","BLOCKER.json","CONTINUATION.json"):
    p=ROOT/name
    if p.is_file():
        try:
            obj=json.loads(p.read_text(encoding="utf-8"))
            if isinstance(obj,dict):
                out[name]={k:obj.get(k) for k in (
                    "state","reason","task_id","attempt","retry_at",
                    "checkpoint","next_action","type"
                ) if k in obj}
        except Exception as exc:
            out[name]={"parse_error":type(exc).__name__}
q=ROOT/"TASK_QUEUE.jsonl"
if q.is_file():
    rows=[]
    for line in q.read_text(encoding="utf-8",errors="replace").splitlines():
        try: obj=json.loads(line)
        except Exception: continue
        if obj.get("task_id")==TASK:
            rows.append({
                "status":obj.get("status"),
                "attempts":obj.get("attempts"),
                "model_policy":obj.get("model_policy"),
                "route_task_id":obj.get("route_task_id"),
                "phase":obj.get("phase")
            })
    out["task_queue"]=rows
print("ERROR_CLASS=R4P2_ASTRA_CURRENT_STATE",flush=True)
print("ERROR="+json.dumps(out,separators=(",",":"),sort_keys=True),flush=True)
raise SystemExit(1)
